<?php
namespace App\Http\Controllers;
use App\Models\Booking; use App\Models\Quote; use App\Support\Workspace; use Illuminate\Http\Request;
class BookingController extends Controller {
    public function index(Request $request) { $b=Workspace::business($request); $query=Booking::where('business_id',$b->id)->with(['customer','service','assignee'])->orderBy('starts_at'); if(!$request->user()->canManageBusiness()) $query->where('assigned_user_id',$request->user()->id); return view('bookings.index',['bookings'=>$query->paginate(30),'business'=>$b]); }
    public function create(Request $request, ?Quote $quote=null) { $b=Workspace::business($request); if($quote) Workspace::assertBusiness($quote,$b); return view('bookings.create',['business'=>$b,'quote'=>$quote,'customers'=>$b->customers()->orderBy('name')->get(),'services'=>$b->services()->where('active',true)->get(),'staff'=>$b->users()->whereIn('role',['owner','admin','staff'])->get()]); }
    public function store(Request $request) { $b=Workspace::business($request); $data=$request->validate(['quote_id'=>'nullable|integer','customer_id'=>'required|integer','service_id'=>'nullable|integer','assigned_user_id'=>'nullable|integer','starts_at'=>'required|date','ends_at'=>'nullable|date|after:starts_at','recurrence'=>'required|in:once,weekly,fortnightly,monthly','notes'=>'nullable|string|max:5000','estimated_total'=>'nullable|numeric|min:0']); foreach(['customer_id'=>'customers','service_id'=>'services','assigned_user_id'=>'users'] as $field=>$table) if(!empty($data[$field])) abort_unless(\Illuminate\Support\Facades\DB::table($table)->where('id',$data[$field])->where('business_id',$b->id)->exists(),404); if(!empty($data['quote_id'])) { $quote=Quote::where('business_id',$b->id)->findOrFail($data['quote_id']); $data['estimated_total']=$quote->total; $data['enquiry_id']=$quote->enquiry_id; } Booking::create($data+['business_id'=>$b->id]); return redirect()->route('bookings.index')->with('status','Booking scheduled.'); }
    public function update(Request $request,Booking $booking) { $b=Workspace::business($request); Workspace::assertBusiness($booking,$b); abort_unless($request->user()->canManageBusiness()||$booking->assigned_user_id===$request->user()->id,403); $data=$request->validate(['status'=>'required|in:scheduled,in_progress,completed,cancelled','completion_notes'=>'nullable|string|max:5000']); $booking->update($data); return back()->with('status','Job status updated.'); }
}
